// Loads the WebAssembly application generated by wasm-bindgen.

// Android's browsers say when notekpr can go on the home screen
// (`beforeinstallprompt`), maybe before the app has loaded: the event is
// kept here for the sign-in screen's offer (src/homescreen.rs), and the
// browser's own bar for it stays away. Listening starts before the app's
// script is even fetched, so the event can't be missed.
window.notekprHomeScreen = null;
addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  window.notekprHomeScreen = e;
});

// The diagram module (crates/diagram, src/diagrams.rs in the app): too big
// to load with the app, loaded the first time a note shows a diagram. Its
// `render(code, dark, font, id)`. `fresh` > 0 loads a new instance (after
// one stopped working: an import is otherwise the same module).
window.notekprDiagrams = async (fresh) => {
  const m = await import("/pkg/notekpr_diagram.js" + (fresh ? "?" + fresh : ""));
  await m.default({ module_or_path: "/pkg/notekpr_diagram_bg.wasm" });
  return m.render;
};

import("/pkg/notekpr_web.js")
  .then((m) => m.default({ module_or_path: "/pkg/notekpr_web_bg.wasm" }))
  .catch((e) => {
    const el = document.getElementById("boot") || document.body;
    el.textContent = "Failed to start notekpr: " + e;
    console.error(e);
  });
